            {%- if '<think>' in content and '</think>' in content %}
                {%- set _think_open = content.find('<think>') %}
                {%- set _think_close = content.find('</think>') %}
                {%- if _think_close > _think_open %}
                    {%- set reasoning_content = content[_think_open + 7:_think_close] | trim('\n') %}
                    {%- set content = content[_think_close + 8:] | lstrip('\n') %}
                {%- endif %}
            {%- endif %}
        {%- endif %}
